class I{String s(boolean P,String[]S){var a=S[0].getBytes();int N=a.length,p[]=new int[N],n=0,r=N-1&-2;long A=0;for(int i=0;i<N;i++){int d=a[i]-=48;p[i]=n;A+=(~i&1L)*i*d*(2*n+d-1)/4;n+=d;}if(P)x:for(int i=1;i<r;i+=2)for(int t,q=p[i];q<p[i+1];q++){while(a[r]<1&r>i)r-=2;t=q+1-a[r]---p[r];if(t>=0)break x;A+=r/2L*t;}else for(int i=r;i>0;i-=2)for(int v=a[i],j=1;j<i;j+=2)if(a[j]>=v){A+=i/2L*v*(p[j]-p[i]);p[j]+=v;a[j]-=v;break;}return""+A;}}
